-- Generated by `npm run db:schema` from a database built from supabase/migrations. Do not edit: change a migration.

CREATE OR REPLACE FUNCTION public.my_deal_listing_ids()
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select o.listing_id from public.offers o
   where o.buyer_id = (select auth.uid())
  union
  select oi.listing_id from public.order_items oi
    join public.orders ord on ord.id = oi.order_id
   where ord.buyer_id = (select auth.uid()) and oi.listing_id is not null;
$function$;

comment on function public.my_deal_listing_ids() is 'OS-W33: ids of listings the caller made an offer on or ordered, for the archived-listing read policies; ids only, the caller''s own; none for a visitor.';

grant execute on function public.my_deal_listing_ids() to anon;
grant execute on function public.my_deal_listing_ids() to authenticated;
grant execute on function public.my_deal_listing_ids() to service_role;
